// Walk from the root config to the module that declared this resource,
// collecting the configuration for each ancestor module that still
// exists in the configuration. A "removed" block referring to a
// resource in a module that has been removed from the configuration
// must be declared in one of the modules that still exists, so we'll
// use the collected ancestors to find it below.
type ancestorConfig struct {
	path   addrs.Module
	config *configs.Config
}
ancestors := make([]ancestorConfig, 0, len(addr.Module)+1)
ancestors = append(ancestors, ancestorConfig{path: nil, config: root})
config := root
for i, name := range addr.Module {
	config = config.Children[name]
	if config == nil {
		break
	}
	ancestors = append(ancestors, ancestorConfig{path: addr.Module[:i+1], config: config})
}

if config == nil {
	// The module containing this resource is no longer in the
	// configuration, so the only configuration available for this
	// resource is a "removed" block declared in one of its ancestor
	// modules, if any.
	var rem *configs.Removed
	for _, anc := range ancestors {
		for _, candidate := range anc.config.Module.Removed {
			crAddr, ok := candidate.From.RelSubject.(addrs.ConfigResource)
			if !ok {
				// Not for a resource at all, so can't possibly match
				continue
			}
			if crAddr.Resource != addr.Resource {
				// Not the same resource
				continue
			}

			// The removed block's address is relative to the module
			// where the removed block was declared, so we need to
			// combine it with that module's address before comparing
			// it with the resource's full module address.
			target := make(addrs.Module, 0, len(anc.path)+len(crAddr.Module))
			target = append(target, anc.path...)
			target = append(target, crAddr.Module...)
			if !target.Equal(addr.Module) {
				continue
			}

			log.Printf("[TRACE] AttachResourceConfigTransformer: attaching to %q (%T) removed block from %#v", dag.VertexName(v), v, candidate.DeclRange)
			rem = candidate
		}
	}
	if rem == nil {
		log.Printf("[TRACE] AttachResourceConfigTransformer: %q (%T) has no configuration available", dag.VertexName(v), v)
		continue
	}
	arn.AttachResourceConfig(nil, rem)
	continue
}

module := config.Module

